<?php require APP_PATH.'Views/layouts/footer.php';?><script>$(function(){const csrf='<?=csrf_token()?>',post=(url,data,fd=false)=>$.ajax({url,type:'POST',data,processData:!fd,contentType:fd?false:'application/x-www-form-urlencoded',dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else Swal.fire('Error',r.message,'error')}).fail(x=>Swal.fire('Error',x.responseJSON?.message||'Request failed.','error'));$('.upload-clearance').click(function(){$('#uploadClearanceId').val($(this).data('id'));bootstrap.Modal.getOrCreateInstance('#uploadModal').show()});$('#uploadForm').submit(function(e){e.preventDefault();post('index.php?page=separation_upload_clearance_document',new FormData(this),true)});$('.update-clearance').click(function(){let c=$(this).data('json');$('#clearanceId').val(c.id);$('#clearanceStatus').val(c.status);$('#accountabilityDetails').val(c.accountability_details);$('#clearanceComments').val(c.comments);bootstrap.Modal.getOrCreateInstance('#clearanceModal').show()});$('#clearanceForm').submit(function(e){e.preventDefault();post('index.php?page=separation_update_clearance',$(this).serialize())});$('.add-asset').click(function(){$('#assetForm')[0].reset();$('#assetId').val('');bootstrap.Modal.getOrCreateInstance('#assetModal').show()});$('.edit-asset').click(function(){let a=$(this).data('json');$('#assetId').val(a.id);$('#assetItem').val(a.item_name);$('#assetSerial').val(a.serial_no);$('#assetCondition').val(a.condition_status);$('#assetReturned').prop('checked',a.returned==1);$('#assetRemarks').val(a.remarks);bootstrap.Modal.getOrCreateInstance('#assetModal').show()});$('#assetForm').submit(function(e){e.preventDefault();post('index.php?page=separation_save_asset',$(this).serialize())});$('#interviewForm').submit(function(e){e.preventDefault();post('index.php?page=separation_save_interview',$(this).serialize())});$('.complete-separation').click(function(){post('index.php?page=separation_complete',{id:$(this).data('id'),csrf_token:csrf})})});</script>
